SELECT orders.channel, SUM(CASE WHEN shipments.status = 'DELIVERED' THEN 1 ELSE 0 END) AS delivered_count, ROUND((100 * SUM(CASE WHEN shipments.status = 'DELIVERED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_delivered FROM shipments INNER JOIN orders ON shipments.order_id = orders.id WHERE orders.amount < 920 GROUP BY orders.channel HAVING SUM(CASE WHEN shipments.status = 'DELIVERED' THEN 1 ELSE 0 END) > 63 ORDER BY delivered_count DESC;
